describe('Async Data Fetching - Non-blocking Initial Page Render', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should render initial page without blocking and display data after async fetch', () => {
    // Verify initial page is visible
    cy.get('[data-testid="page-title"]').should('be.visible');
    cy.get('[data-testid="dashboard-header"]').should('be.visible');

    // Verify initial content is loaded
    cy.get('[data-testid="dashboard-stats"]').should('be.visible');
    cy.get('[data-testid="dashboard-stats"]').should('contain', 'Loading');

    // Wait for async data fetch
    cy.intercept('GET', '/api/dashboard/stats').as('fetchStats');
    cy.wait('@fetchStats');

    // Verify async data is displayed
    cy.get('[data-testid="dashboard-stats"]').should('contain', 'Data loaded');
    cy.get('[data-testid="dashboard-stats"]').should('contain', 'Total Users');
    cy.get('[data-testid="dashboard-stats"]').should('contain', 'Active Users');

    // Verify other non-blocking elements are visible
    cy.get('[data-testid="dashboard-nav"]').should('be.visible');
    cy.get('[data-testid="dashboard-charts"]').should('be.visible');
  });

  it('should handle error during async data fetch and display error state', () => {
    // Verify initial page is visible
    cy.get('[data-testid="page-title"]').should('be.visible');

    // Intercept with error response
    cy.intercept('GET', '/api/dashboard/stats', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('fetchStatsError');

    // Wait for error response
    cy.wait('@fetchStatsError');

    // Verify error state is displayed
    cy.get('[data-testid="dashboard-stats"]').should('be.visible');
    cy.get('[data-testid="dashboard-stats"]').should('contain', 'Error loading data');

    // Verify error message is shown
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Failed to load dashboard stats');

    // Verify user can retry or navigate away
    cy.get('[data-testid="retry-button"]').should('be.visible');
    cy.get('[data-testid="retry-button"]').click();

    // Wait for retry
    cy.intercept('GET', '/api/dashboard/stats').as('fetchStatsRetry');
    cy.wait('@fetchStatsRetry');

    // Verify data is now loaded
    cy.get('[data-testid="dashboard-stats"]').should('contain', 'Data loaded');
  });
});
